{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (0.00–0.67) and model overestimates prices, especially after recent spikes.",
    "Reduce forecast magnitude by 5–10% if model shows persistent overshoots in the 3rd–5th day of the 30-day horizon.",
    "Apply mean reversion bias: if 3–5 consecutive forecast days are above 10% above historical mean, reduce forecast by 10–15%.",
    "Increase forecast sensitivity to sentiment shifts: if sentiment rises >0.33, adjust forecast downward by 2–5% to reflect market cooling.",
    "Avoid overreacting to short-term volatility: if true outcome deviates >15% from forecast on day 1–3, apply lag correction by reducing forecast by 3–7% for day 4+.",
    "For horizon >15 days, apply smoothing: if forecast variance exceeds 5% of mean, reduce forecast by 2–5% to align with sentiment stability."
  ]
}
